Object.assign(SNIP,{"l38ba": "int lonNhat(int a, int b) { return a > b ? a : b; }\ndouble lonNhat(double a, double b) { return a > b ? a : b; }\nstring lonNhat(string a, string b) { return a > b ? a : b; }\n// ... char, long long, Diem ... : thân hàm giống hệt nhau, chỉ khác kiểu", "l38syn": "template <typename T>          // T là tham số mẫu: \"một kiểu nào đó\"\nT lonNhat(T a, T b) {\n    return a > b ? a : b;\n}\n\nlonNhat(3, 7);                 // T = int    → trình biên dịch sinh lonNhat<int>\nlonNhat(2.5, 1.5);             // T = double → sinh thêm lonNhat<double>\nlonNhat<double>(3, 2.5);       // ghi rõ T = double: 3 được đổi sang 3.0"});PRESET_NOTES["l38"]={"Ví dụ: Một hàm mẫu, nhiều kiểu": "Bốn kiểu khác nhau (int, double, char, string) nên trình biên dịch sinh bốn bản. Lời gọi cuối lonNhat(10, 4) dùng lại bản lonNhat<int> đã có, không sinh thêm. Với string, > so sánh theo thứ tự từ điển nên \"binh\" lớn hơn \"an\".", "Lỗi: Hai đối số khác kiểu": "Đối số 3 cho T = int, đối số 2.5 cho T = double: mâu thuẫn. Khi suy kiểu, C++ không tự đổi int sang double, nên không có bản nào khớp. Sửa: lonNhat<double>(3, 2.5) hoặc lonNhat(3.0, 2.5).", "Ví dụ: Ghi rõ kiểu": "Đã ghi rõ T nên đối số được đổi kiểu như hàm thường: lonNhat<double>(3, 2.5) so 3.0 với 2.5. lonNhat<int>(3, 2.5) đổi 2.5 thành 2 (mất phần lẻ). lonNhat<char>(65, 66) trả về 'B' vì 66 là mã của B.", "Ví dụ: Mẫu với vector": "T được suy từ kiểu phần tử của vector. T() là “giá trị rỗng” của T: 0 với int, 0.0 với double, chuỗi rỗng với string, nên cùng một thân hàm cộng được số và nối được chuỗi.", "Ví dụ: Hai tham số mẫu và hằng số mẫu": "inCap có hai tham số mẫu độc lập nên (1, 2.5) hợp lệ: T = int, U = double. lapLai<3> và lapLai<2> là hai bản khác nhau: N là hằng số được điền vào lúc biên dịch, không truyền lúc chạy.", "Lỗi: Kiểu thiếu toán tử mẫu cần": "Suy kiểu thành công (T = Diem), nhưng khi sinh bản lonNhat<Diem>, dòng a > b không biên dịch được vì Diem không có toán tử >. Lỗi nằm trong thân mẫu, còn nguyên nhân ở chỗ gọi. Sửa: viết bool operator>(const Diem&) const cho Diem (xem ví dụ kế tiếp).", "Ví dụ: Kiểu tự viết dùng được mẫu": "nhoNhat chỉ đòi T có toán tử < và chép được. Diem nạp chồng < (so khoảng cách tới gốc tọa độ) và <<, nên dùng chung mẫu với int, double. (1, 1) gần gốc nhất.", "Ví dụ: Hàm thường được ưu tiên": "lonNhat(3, 7) khớp hoàn toàn với cả hàm thường lẫn bản mẫu lonNhat<int>; khi ngang nhau, C++ chọn hàm thường. Với double chỉ mẫu khớp. Viết lonNhat<int>(...) thì bắt buộc dùng mẫu.", "Ví dụ: Đệ quy trong hàm mẫu": "Bên trong luyThua<int>, lời gọi luyThua(x, n - 1) suy ra lại T = int nên gọi chính bản đó. Ba kiểu int, double, long long cho ba bản; 2 mũ 40 vượt int nên phải dùng 2LL."};EX_HINTS["l38"]=[["Ba phép so sánh và đổi chỗ đủ để sắp ba phần tử: (a, b), (b, c), rồi (a, b) lần nữa.", "Tham số phải là tham chiếu T& thì việc đổi chỗ mới có tác dụng với biến ở main."], ["T được suy từ cả hai tham số: vector<int> và int cùng cho T = int.", "So sánh bằng ==: int và string đều có toán tử này."], ["T() cho giá trị 0 của mọi kiểu số: bắt đầu tổng bằng T s = T();", "lonNhat bắt đầu từ v[0] (không bắt đầu từ 0, vì dãy có thể toàn số âm)."]];
/* ===================== BÀI 38 · Hàm mẫu (function template) ===================== */
/* Bài 38 · Hàm mẫu (function template)
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P38=[{label:"Ví dụ: Một hàm mẫu, nhiều kiểu",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\ntemplate <typename T>\nT lonNhat(T a, T b) {\n    return a > b ? a : b;\n}\n\nint main() {\n    cout << lonNhat(3, 7) << \"\\n\";\n    cout << lonNhat(2.5, 1.5) << \"\\n\";\n    cout << lonNhat('a', 'z') << \"\\n\";\n    string s = \"an\", t = \"binh\";\n    cout << lonNhat(s, t) << \"\\n\";\n    cout << lonNhat(10, 4) << \"\\n\";\n    return 0;\n}",viz:[{type:"tmpl"}]},{label:"Lỗi: Hai đối số khác kiểu",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\ntemplate <typename T>\nT lonNhat(T a, T b) {\n    return a > b ? a : b;\n}\n\nint main() {\n    cout << lonNhat(3, 2.5) << \"\\n\";\n    return 0;\n}"},{label:"Ví dụ: Ghi rõ kiểu",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\ntemplate <typename T>\nT lonNhat(T a, T b) {\n    return a > b ? a : b;\n}\n\nint main() {\n    cout << lonNhat<double>(3, 2.5) << \"\\n\";\n    cout << lonNhat<int>(3, 2.5) << \"\\n\";\n    cout << lonNhat<char>(65, 66) << \"\\n\";\n    return 0;\n}",viz:[{type:"tmpl"}]},{label:"Ví dụ: Mẫu với vector",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\ntemplate <typename T>\nT tong(const vector<T>& v) {\n    T s = T();\n    for (const T& x : v) {\n        s += x;\n    }\n    return s;\n}\n\ntemplate <typename T>\nvoid inDay(const vector<T>& v) {\n    for (int i = 0; i < (int)v.size(); i++) {\n        cout << (i ? \", \" : \"\") << v[i];\n    }\n    cout << \"\\n\";\n}\n\nint main() {\n    vector<int> a = {3, 1, 4};\n    vector<double> b = {0.5, 1.25};\n    vector<string> c = {\"ab\", \"cd\", \"ef\"};\n    inDay(a);\n    inDay(c);\n    cout << tong(a) << \" \" << tong(b) << \" \" << tong(c) << \"\\n\";\n    return 0;\n}",viz:[{type:"tmpl"}]},{label:"Ví dụ: Hai tham số mẫu và hằng số mẫu",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\ntemplate <typename T, typename U>\nvoid inCap(T a, U b) {\n    cout << a << \" | \" << b << \"\\n\";\n}\n\ntemplate <int N>\nstring lapLai(string s) {\n    string kq = \"\";\n    for (int i = 0; i < N; i++) {\n        kq += s;\n    }\n    return kq;\n}\n\nint main() {\n    inCap(1, 2.5);\n    inCap('x', string(\"chu\"));\n    inCap(7, 8);\n    cout << lapLai<3>(\"ab\") << \"\\n\";\n    cout << lapLai<2>(\"xyz\") << \"\\n\";\n    return 0;\n}",viz:[{type:"tmpl"}]},{label:"Lỗi: Kiểu thiếu toán tử mẫu cần",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nstruct Diem {\n    int x, y;\n};\n\ntemplate <typename T>\nT lonNhat(T a, T b) {\n    return a > b ? a : b;\n}\n\nint main() {\n    Diem p{1, 2}, q{3, 4};\n    Diem r = lonNhat(p, q);\n    cout << r.x << \" \" << r.y << \"\\n\";\n    return 0;\n}"},{label:"Ví dụ: Kiểu tự viết dùng được mẫu",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nstruct Diem {\n    int x, y;\n    bool operator<(const Diem& o) const {\n        return x * x + y * y < o.x * o.x + o.y * o.y;\n    }\n};\n\nostream& operator<<(ostream& os, const Diem& d) {\n    return os << \"(\" << d.x << \", \" << d.y << \")\";\n}\n\ntemplate <typename T>\nT nhoNhat(const T a[], int n) {\n    T m = a[0];\n    for (int i = 1; i < n; i++) {\n        if (a[i] < m) m = a[i];\n    }\n    return m;\n}\n\nint main() {\n    int a[] = {5, 2, 8, 1};\n    double b[] = {2.5, -1.5};\n    Diem d[] = {{3, 4}, {1, 1}, {0, 2}};\n    cout << nhoNhat(a, 4) << \" \" << nhoNhat(b, 2) << \"\\n\";\n    cout << nhoNhat(d, 3) << \"\\n\";\n    return 0;\n}",viz:[{type:"tmpl"}]},{label:"Ví dụ: Hàm thường được ưu tiên",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\ntemplate <typename T>\nT lonNhat(T a, T b) {\n    cout << \"[mau] \";\n    return a > b ? a : b;\n}\n\nint lonNhat(int a, int b) {\n    cout << \"[thuong] \";\n    return a > b ? a : b;\n}\n\nint main() {\n    cout << lonNhat(3, 7) << \"\\n\";\n    cout << lonNhat(2.5, 1.5) << \"\\n\";\n    cout << lonNhat<int>(3, 7) << \"\\n\";\n    return 0;\n}",viz:[{type:"tmpl"}]},{label:"Ví dụ: Đệ quy trong hàm mẫu",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\ntemplate <typename T>\nT luyThua(T x, int n) {\n    if (n == 0) return T(1);\n    return x * luyThua(x, n - 1);\n}\n\nint main() {\n    cout << luyThua(2, 10) << \"\\n\";\n    cout << luyThua(1.5, 3) << \"\\n\";\n    cout << luyThua(2LL, 40) << \"\\n\";\n    return 0;\n}",viz:[{type:"tmpl"}]}];
const sim38=makeSim2(document.getElementById("sim-l38"),{id:"s38",presets:P38});
makeEx2(document.getElementById("ex-l38"),sim38,[{t:"Sắp xếp ba giá trị",d:"Viết hàm mẫu <code>doiCho(T&amp; a, T&amp; b)<\/code> và <code>sap3(T&amp; a, T&amp; b, T&amp; c)<\/code> sắp ba giá trị tăng dần (dùng doiCho). Dòng nhập gồm kiểu (<code>int<\/code>, <code>double<\/code> hoặc <code>string<\/code>) rồi ba giá trị cùng kiểu. In ba giá trị sau khi sắp, cách nhau một dấu cách.",tests:[{in:"int 3 1 2",out:"1 2 3"},{in:"string chuoi an binh",out:"an binh chuoi"},{in:"double 2.5 -1 2.25",out:"-1 2.25 2.5"},{in:"int 5 5 1",out:"1 5 5"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\n// viết template doiCho và sap3\n\nint main() {\n    string kieu;\n    cin >> kieu;\n    if (kieu == \"int\") {\n        int a, b, c;\n        cin >> a >> b >> c;\n        // sap3(a, b, c); in\n    } else if (kieu == \"double\") {\n        double a, b, c;\n        cin >> a >> b >> c;\n    } else {\n        string a, b, c;\n        cin >> a >> b >> c;\n    }\n    return 0;\n}",need:/template\s*<\s*(typename|class)\s+\w+\s*>\s*void\s+doiCho[\s\S]*template\s*<\s*(typename|class)\s+\w+\s*>\s*void\s+sap3/,needMsg:"Hãy viết doiCho và sap3 dưới dạng hàm mẫu (template <typename T>)."},{t:"Tìm vị trí",d:"Viết hàm mẫu <code>int timViTri(const vector&lt;T&gt;&amp; v, const T&amp; x)<\/code> trả về chỉ số đầu tiên của x trong v, hoặc -1 nếu không có. Nhập n và n số nguyên, rồi q và q số cần tìm; tiếp theo m và m từ, rồi r và r từ cần tìm. In kết quả mỗi lần tìm trên một dòng.",tests:[{in:"4\n5 3 5 9\n2\n5 7\n3\nan binh an\n2\nbinh chi",out:"0\n-1\n1\n-1"},{in:"1\n0\n1\n0\n1\nx\n1\nx",out:"0\n0"},{in:"3\n-1 -2 -3\n3\n-3 -2 -1\n2\nb a\n1\na",out:"2\n1\n0\n1"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\n// viết template timViTri\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> a(n);\n    for (int i = 0; i < n; i++) cin >> a[i];\n    int q;\n    cin >> q;\n    for (int i = 0; i < q; i++) {\n        int x;\n        cin >> x;\n        // in timViTri(a, x)\n    }\n    int m;\n    cin >> m;\n    vector<string> s(m);\n    for (int i = 0; i < m; i++) cin >> s[i];\n    int r;\n    cin >> r;\n    for (int i = 0; i < r; i++) {\n        string x;\n        cin >> x;\n        // in timViTri(s, x)\n    }\n    return 0;\n}",need:/template\s*<\s*(typename|class)\s+\w+\s*>\s*int\s+timViTri/,needMsg:"Hãy viết timViTri dưới dạng hàm mẫu: template <typename T> int timViTri(...)."},{t:"Thống kê hai dãy",d:"Viết hai hàm mẫu <code>T tongCong(const vector&lt;T&gt;&amp; v)<\/code> và <code>T lonNhat(const vector&lt;T&gt;&amp; v)<\/code> (v không rỗng). Nhập n và n số nguyên (long long), rồi m và m số thực. In hai dòng: <code>Nguyen: tong lon_nhat<\/code> và <code>Thuc: tong lon_nhat<\/code> (số thực in mặc định của cout).",tests:[{in:"3\n1 5 2\n2\n0.5 1.25",out:"Nguyen: 8 5\nThuc: 1.75 1.25"},{in:"2\n1000000000000 -3\n1\n-2.5",out:"Nguyen: 999999999997 1000000000000\nThuc: -2.5 -2.5"},{in:"1\n-7\n3\n1 2 3",out:"Nguyen: -7 -7\nThuc: 6 3"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\n// viết template tongCong và lonNhat\n\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (int i = 0; i < n; i++) cin >> a[i];\n    int m;\n    cin >> m;\n    vector<double> b(m);\n    for (int i = 0; i < m; i++) cin >> b[i];\n    // in hai dòng\n    return 0;\n}",need:/template\s*<\s*(typename|class)\s+\w+\s*>\s*\w+\s+tongCong[\s\S]*template\s*<\s*(typename|class)\s+\w+\s*>\s*\w+\s+lonNhat/,needMsg:"Hãy viết tongCong và lonNhat dưới dạng hàm mẫu."}]);

makeQuiz("quiz38","score38",[{"q": "Khi nào trình biên dịch sinh mã máy cho một hàm mẫu?", "o": ["Ngay khi đọc tới dòng template", "Khi hàm mẫu được dùng với một bộ kiểu cụ thể, mỗi bộ kiểu một bản", "Khi chương trình chạy tới lời gọi", "Chỉ một lần cho mọi kiểu"], "a": 1, "e": "Mẫu chỉ là bản thiết kế; mỗi bộ kiểu được dùng sinh ra một bản cụ thể lúc biên dịch."}, {"q": "Với <code>template &lt;typename T&gt; T lonNhat(T a, T b)<\/code>, lời gọi <code>lonNhat(3, 2.5)<\/code> thì sao?", "o": ["Trả về 3", "Trả về 3.0", "Lỗi biên dịch: T suy ra vừa là int vừa là double", "Tự đổi 2.5 thành 2"], "a": 2, "e": "Khi suy kiểu, trình biên dịch không tự đổi kiểu; ghi rõ lonNhat<double>(3, 2.5) để sửa."}, {"q": "Trong <code>template &lt;...&gt;<\/code>, viết <code>typename T<\/code> và <code>class T<\/code> khác nhau thế nào?", "o": ["class T chỉ nhận kiểu là lớp", "typename T chỉ nhận kiểu có sẵn", "Như nhau", "class T làm hàm chạy nhanh hơn"], "a": 2, "e": "Ở vị trí này hai từ khóa đồng nghĩa; T có thể là int, string hay lớp tự viết."}, {"q": "Có cả <code>int lonNhat(int, int)<\/code> (hàm thường) và hàm mẫu <code>lonNhat(T, T)<\/code>. <code>lonNhat(2, 3)<\/code> gọi bản nào?", "o": ["Hàm mẫu lonNhat<int>", "Hàm thường", "Lỗi mơ hồ", "Cả hai"], "a": 1, "e": "Khi khớp ngang nhau, hàm thường được ưu tiên hơn hàm mẫu."}]);

